pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow more flexibility as the stream ends.
    // The core objective is to minimize post_residual (Best Fit), but we apply non-linear
    // corrections to avoid creating "dead zones" that cannot fit upcoming items.

    let mut score = post * 1.5;

    // Penalty for creating a bin with a residual that is too small to be useful
    // (e.g., between 1 and 9), as these are often "wasted" space.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Lookahead: if the next item is large, penalize small post_residuals that 
    // would force the next item into a new bin.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Dynamic threshold: If we have many open bins, prioritize filling them tightly.
    // If we are near the end of the stream, prioritize closing bins (minimizing open_bins_count).
    score += (open_bins_count as f64 * 2.0) * (1.0 - progress);

    // If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high, but decreases as we exhaust options
        // or as the stream progresses and we need to avoid fragmented bins.
        score = 85.0 - (progress * 20.0);

        // If only one bin can fit the item, opening a new one is usually inefficient.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. Lower score = better fit.

    // 1. Base penalty: The tighter the fit, the better (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Lookahead optimization: If next_item_size is large, favor larger residuals.
    // If post_residual is smaller than next_item_size, we penalize the current placement 
    // to keep space for the future item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. Global state: Penalize opening new bins when current bins are underutilized.
    // If we are considering a new bin (bin_residual == bin_capacity), penalize based on 
    // the current density of the system.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5;
        // As the stream progresses, make it harder to open new bins.
        let progress = step_index as f64 / total_items as f64;
        score += (progress * 50.0);
    }

    // 4. Critical thresholding: If this is the only bin that fits, prioritize it heavily
    // to avoid unnecessary bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Fragmentation control: Heavily penalize leaving tiny, unusable gaps (e.g., < 10).
    // An item size is at least 1, but if we leave a gap that is likely too small 
    // for future items, add a penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 6. Balance: Reward placements that bring the bin residual closer to the global mean,
    // encouraging uniform bin filling.
    let diff_to_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_to_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the remaining space is too small to fit the smallest possible 
    // items (often ~10), heavily penalize it to avoid unusable shards.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, 
    // favor this bin by reducing the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin (not a new one), 
    // penalize based on the count of open bins to encourage consolidation.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    } else {
        // 4. New bin penalty: Only open a new bin if the current fit is truly terrible.
        // We add a threshold penalty to the "new bin" candidate (where bin_residual == bin_capacity).
        score += 45.0;
    }

    // 5. Fitting bin scarcity: If this is the only bin that can fit the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Mean residual balancing: Penalize bins that are significantly emptier than the average 
    // to keep the bin fill-levels somewhat uniform.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented with lookahead and bin-density balancing.
    // We aim to minimize the post-residual space (Best Fit), but penalize leaving gaps 
    // that are too small for the predicted next item.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize smaller post-residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: discourage unless necessary or late in the stream
    if is_new_bin {
        // If we have fitting bins, opening a new one is expensive
        score += if fitting_bins_count > 0 { 40.0 + (progress * 20.0) } else { 0.0 };
    } else {
        // Lookahead penalty: if post_residual is too small to fit the next item, 
        // we might be creating 'dead space'.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 15.0; // Penalty for creating a gap that can't fit the next known item
        }

        // Global state awareness: if this bin is significantly emptier than the average, 
        // prioritize filling it to keep the "average occupancy" high.
        let deviation = bin_residual as f64 - mean_residual;
        if deviation > 0.0 {
            score -= (deviation * 0.5); // Favor bins that are currently emptier
        }
    }

    // Critical threshold: if we are down to the last fitting bin, prioritize it 
    // to avoid opening a new one prematurely.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Dynamic scaling: as the stream progresses, prioritize tighter packing
    score += (1.0 - progress) * (post_residual as f64 * 0.2);

    score
}

