pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" (residual too small to fit common items)
    // We penalize residuals in the [1, 9] range heavily as they are mostly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If a next item exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that can accommodate the next item
            score -= 10.0;
        }
    }

    // Global state awareness: 
    // If we have many open bins, penalize opening a new one (is_new_bin)
    if is_new_bin {
        score += (open_bins_count as f64 * 2.0);
        // Late game: be more conservative about opening new bins
        if progress > 0.8 {
            score += 20.0;
        }
    }

    // Fitting efficiency:
    // If this is the only bin that can fit the item, give it a significant priority boost
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Mean residual balance:
    // Penalize bins that deviate significantly from the average occupancy
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}
